import { useEffect, useMemo, useState } from "react";
import { AlertCircle, ArrowRight, Bell, Check, ChevronRight, CircleHelp, Database, FileCheck2, Filter, Layers3, LogOut, MapPin, Menu, Plus, Search, Settings2, ShieldCheck, Upload, UsersRound, X } from "lucide-react";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import AccountDialog from "@/components/AccountDialog";

type Section = "Overview" | "Borehole register" | "Applications" | "GIS screening" | "Inspections" | "Follow-up actions" | "Reports" | "Notifications" | "Administration";
type RecordView = { id: number; recordCode: string; district: string; siteName: string; purpose: string; operationalStatus: string; applicationStatus: string; screeningStatus: string; latitude: string; longitude: string; updatedAt: Date; createdBy: number; partyId?: number | null; locationDescription?: string | null; technicalDetailsJson?: string | null; commissionedAt?: Date | null; decommissionedAt?: Date | null; decommissionReason?: string | null };
type WorkspaceData = { layers: Array<{ layerKey: string; name: string; sourceKey: string; version: string; geometryJson: string | null; datasetDate: Date | null; coordinateReferenceSystem: string; coverageJson: string | null; accuracyNotes: string | null; licenseNotes: string | null; verificationStatus: string; active: boolean }>; settings: { jurisdiction: string; coordinatingAuthority: string; localAuthorityLabel: string; localAuthorityValue: string | null; publicHosting: string; privateHosting: string; workflow: unknown }; roles: Array<{ roleKey: string; name: string; permissionsJson: string }>; sources: Array<{ sourceKey: string; name: string; purpose: string; accessLevel: string; referenceOnly: boolean; accessStatus: string; metadataJson: string | null }>; rules: Array<{ ruleKey: string; name: string; version: string; jurisdiction: string; hazardType: string; conditionJson: string; sourceKey: string; sourceReference: string | null; explanation: string; active: boolean; approvedBy: string | null; effectiveAt: Date | null }>; permissions: string[] };
type EvidenceMime = "application/pdf" | "image/jpeg" | "image/png";

function isEvidenceMime(value: string): value is EvidenceMime {
  return value === "application/pdf" || value === "image/jpeg" || value === "image/png";
}

function Badge({ children, tone = "neutral" }: { children: React.ReactNode; tone?: string }) { return <span className={`badge badge-${tone}`}>{children}</span>; }
function Notice({ children, tone = "neutral" }: { children: React.ReactNode; tone?: string }) { return <div className={`notice-card notice-${tone}`}><AlertCircle size={17} /><div>{children}</div></div>; }
function TitleBlock({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail: string; action?: React.ReactNode }) { return <div className="page-title-row"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{detail}</p></div>{action}</div>; }

export default function Home() {
  const auth = useAuth({ redirectOnUnauthenticated: true });
  const workspace = trpc.borewatch.workspace.get.useQuery(undefined, { enabled: auth.isAuthenticated, retry: false });
  const recordsQuery = trpc.borewatch.boreholes.list.useQuery(undefined, { enabled: auth.isAuthenticated && Boolean(workspace.data), retry: false });
  const applicationsQuery = trpc.borewatch.applications.list.useQuery(undefined, { enabled: auth.isAuthenticated && Boolean(workspace.data), retry: false });
  const inspectionsQuery = trpc.borewatch.inspections.list.useQuery(undefined, { enabled: auth.isAuthenticated && Boolean(workspace.data?.permissions.includes("inspection:view_assigned") || workspace.data?.permissions.includes("*")), retry: false });
  const inspectorsQuery = trpc.borewatch.inspections.assignees.useQuery(undefined, { enabled: auth.isAuthenticated && Boolean(workspace.data?.permissions.includes("inspection:assign") || workspace.data?.permissions.includes("*")), retry: false });
  const followUpsQuery = trpc.borewatch.followUps.list.useQuery(undefined, { enabled: auth.isAuthenticated && Boolean(workspace.data?.permissions.includes("inspection:view_assigned") || workspace.data?.permissions.includes("*")), retry: false });
  const usersQuery = trpc.borewatch.administration.users.useQuery(undefined, { enabled: auth.isAuthenticated && auth.user?.role === "admin", retry: false });
  const notificationsQuery = trpc.borewatch.notifications.list.useQuery(undefined, { enabled: auth.isAuthenticated && Boolean(workspace.data), refetchInterval: 30000, retry: false });
  const markNotificationRead = trpc.borewatch.notifications.markRead.useMutation({ onSuccess: () => void notificationsQuery.refetch() });
  const markAllNotificationsRead = trpc.borewatch.notifications.markAllRead.useMutation({ onSuccess: () => void notificationsQuery.refetch() });
  const createInspection = trpc.borewatch.inspections.create.useMutation({ onSuccess: () => void inspectionsQuery.refetch() });
  const submitInspection = trpc.borewatch.inspections.submit.useMutation({ onSuccess: () => void inspectionsQuery.refetch() });
  const startInspection = trpc.borewatch.inspections.start.useMutation({ onSuccess: () => void inspectionsQuery.refetch() });
  const reviewInspection = trpc.borewatch.inspections.review.useMutation({ onSuccess: () => void inspectionsQuery.refetch() });
  const createFollowUp = trpc.borewatch.followUps.create.useMutation({ onSuccess: () => void followUpsQuery.refetch() });
  const updateFollowUp = trpc.borewatch.followUps.update.useMutation({ onSuccess: () => void followUpsQuery.refetch() });
  const assessScreening = trpc.borewatch.screening.assess.useMutation({ onSuccess: () => void recordsQuery.refetch() });
  const assignRole = trpc.borewatch.administration.assignRole.useMutation({ onSuccess: () => void usersQuery.refetch() });
  const removeRole = trpc.borewatch.administration.removeRole.useMutation({ onSuccess: () => void usersQuery.refetch() });
  const createRecord = trpc.borewatch.boreholes.create.useMutation({ onSuccess: () => void recordsQuery.refetch() });
  const updateRecord = trpc.borewatch.boreholes.update.useMutation({ onSuccess: () => void recordsQuery.refetch() });
  const createApplication = trpc.borewatch.applications.create.useMutation({ onSuccess: () => void applicationsQuery.refetch() });
  const transition = trpc.borewatch.applications.transition.useMutation({ onSuccess: () => void applicationsQuery.refetch() });
  const [active, setActive] = useState<Section>("Overview");
  const [mobileNav, setMobileNav] = useState(false);
  const [query, setQuery] = useState("");
  const [selectedRecord, setSelectedRecord] = useState<RecordView | null>(null);
  const [showRecordForm, setShowRecordForm] = useState(false);
  const [showApplicationForm, setShowApplicationForm] = useState(false);
  const [applicationType, setApplicationType] = useState("borehole_registration");
  const [applicationBoreholeId, setApplicationBoreholeId] = useState("");
  const [applicationCompleteness, setApplicationCompleteness] = useState<Record<string, boolean>>({});
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [toast, setToast] = useState("");
  const [siteName, setSiteName] = useState("");
  const [district, setDistrict] = useState("");
  const [purpose, setPurpose] = useState("");
  const [locationDescription, setLocationDescription] = useState("");
  const [wellDepth, setWellDepth] = useState("");
  const [constructionNotes, setConstructionNotes] = useState("");
  const [coordinateAccuracy, setCoordinateAccuracy] = useState("");
  const [coordinateCapturedDate, setCoordinateCapturedDate] = useState("");
  const [partyName, setPartyName] = useState("");
  const [partyOrganization, setPartyOrganization] = useState("");
  const [partyEmail, setPartyEmail] = useState("");
  const [partyPhone, setPartyPhone] = useState("");
  const [latitude, setLatitude] = useState("");
  const [longitude, setLongitude] = useState("");
  const [authority, setAuthority] = useState("");

  useEffect(() => { if (workspace.data?.settings.localAuthorityValue) setAuthority(workspace.data.settings.localAuthorityValue); }, [workspace.data?.settings.localAuthorityValue]);
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(""), 3500); };
  const records = (recordsQuery.data ?? []) as RecordView[];
  const applications = applicationsQuery.data ?? [];
  const filtered = useMemo(() => records.filter((record) => `${record.recordCode} ${record.siteName} ${record.district} ${record.purpose}`.toLowerCase().includes(query.toLowerCase())), [records, query]);
  const saveRecord = async (event: React.FormEvent) => {
    event.preventDefault();
    try { await createRecord.mutateAsync({ siteName, district, purpose, locationDescription: locationDescription || undefined, responsibleParty: { displayName: partyName, organization: partyOrganization || undefined, contactEmail: partyEmail || undefined, contactPhone: partyPhone || undefined }, technicalDetails: { coordinateReferenceSystem: "EPSG:4326", ...(coordinateAccuracy ? { coordinateAccuracyM: coordinateAccuracy } : {}), ...(coordinateCapturedDate ? { coordinateCapturedDate } : {}), ...(wellDepth ? { totalDepthM: wellDepth } : {}), ...(constructionNotes ? { construction: constructionNotes } : {}) }, latitude, longitude, localAuthorityValue: authority || undefined }); setSiteName(""); setDistrict(""); setPurpose(""); setLocationDescription(""); setWellDepth(""); setConstructionNotes(""); setCoordinateAccuracy(""); setCoordinateCapturedDate(""); setPartyName(""); setPartyOrganization(""); setPartyEmail(""); setPartyPhone(""); setLatitude(""); setLongitude(""); setShowRecordForm(false); notify("Borehole record saved to the project database."); } catch (error) { notify(error instanceof Error ? error.message : "Unable to save borehole record"); }
  };
  const saveApplication = async (event: React.FormEvent) => { event.preventDefault(); try { await createApplication.mutateAsync({ applicationType, boreholeId: applicationBoreholeId ? Number(applicationBoreholeId) : undefined, completeness: applicationCompleteness, localAuthorityValue: authority || undefined }); setShowApplicationForm(false); setApplicationBoreholeId(""); notify("Application draft created."); } catch (error) { notify(error instanceof Error ? error.message : "Unable to create application"); } };

  if (auth.loading) return <div className="auth-state"><ShieldCheck size={24} /><b>Loading authenticated workspace…</b></div>;
  if (auth.error) return <div className="auth-state" role="alert"><AlertCircle size={24} /><b>Unable to verify your sign-in.</b><p>{auth.error.message}</p><a className="button button-primary" href="/login">Return to sign in</a></div>;
  if (workspace.isLoading) return <div className="auth-state"><ShieldCheck size={24} /><b>Loading authenticated workspace…</b></div>;
  if (!auth.user) return <div className="auth-state"><AlertCircle size={24} /><b>You are not signed in.</b><a className="button button-primary" href="/login">Sign in</a></div>;
  if (workspace.error || !workspace.data) return <div className="auth-state"><AlertCircle size={24} /><b>Workspace configuration is unavailable.</b><p>Configure DATABASE_URL and apply the Drizzle migrations before using BoreWatch.</p></div>;
  const settings = workspace.data.settings;
  const permissions = new Set(workspace.data.permissions);
  const canCreateRecord = permissions.has("*") || permissions.has("record:create");
  const canCreateApplication = permissions.has("*") || permissions.has("application:create");
  const nav: Array<{ name: Section; icon: typeof Database }> = [{ name: "Overview", icon: Database }, { name: "Borehole register", icon: Database }, { name: "Applications", icon: FileCheck2 }, { name: "GIS screening", icon: MapPin }, ...(permissions.has("inspection:view_assigned") || permissions.has("*") ? [{ name: "Inspections" as Section, icon: Check }, { name: "Follow-up actions" as Section, icon: AlertCircle }] : []), ...(permissions.has("report:view") || permissions.has("*") ? [{ name: "Reports" as Section, icon: FileCheck2 }] : []), { name: "Notifications", icon: Bell }, ...(auth.user.role === "admin" || permissions.has("layer:configure") || permissions.has("workflow:configure") || permissions.has("audit:view") ? [{ name: "Administration" as Section, icon: Settings2 }] : [])];
  const open = (section: Section) => { setActive(section); setMobileNav(false); setSelectedRecord(null); };
  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? "sidebar-open" : ""}`}><div className="brand"><div className="brand-mark" aria-hidden="true"><span /><i /></div><div><strong>BOREWATCH</strong><small>GROUNDWATER OVERSIGHT</small></div><button className="icon-button" onClick={() => setMobileNav(false)} aria-label="Close navigation"><X size={17} /></button></div><div className="workspace-select"><div className="workspace-monogram">{settings.jurisdiction.slice(0, 1)}</div><div><b>{settings.jurisdiction}</b><small>{settings.coordinatingAuthority}</small></div></div><nav className="side-nav">{nav.map(({ name, icon: Icon }) => <button className={`nav-link ${active === name ? "active" : ""}`} key={name} onClick={() => open(name)}><Icon size={17} /><span>{name}</span></button>)}</nav><div className="sidebar-bottom"><div className="pilot-note"><ShieldCheck size={16} /><div><b>Authenticated workspace</b><p>Server-backed records and protected permissions.</p><button onClick={() => notify("Public information is separate from authenticated records.")}>Hosting boundary <ArrowRight size={12} /></button></div></div><div className="profile-row-wrap"><button className="profile-row profile-row-clickable" onClick={() => setShowAccountModal(true)} title="View account profile and permissions" aria-label="Open account settings"><div className="avatar avatar-teal">{(auth.user.name ?? auth.user.email ?? "U").slice(0, 2).toUpperCase()}</div><span className="profile-info"><b>{auth.user.name ?? auth.user.email}</b><small>{auth.user.role === "admin" ? "Platform Admin" : "Authorized User"}</small></span><Settings2 size={15} className="profile-gear" /></button><button className="quick-logout-btn" onClick={() => void auth.logout()} title="Sign out" aria-label="Sign out"><LogOut size={15} /></button></div></div></aside>
    {mobileNav && <button className="nav-scrim" onClick={() => setMobileNav(false)} aria-label="Close navigation" />}
    <div className="main-column"><header className="topbar"><button className="mobile-menu" onClick={() => setMobileNav(true)} aria-label="Open navigation"><Menu size={21} /></button><div className="crumb"><span>{settings.jurisdiction}</span><ChevronRight size={14} /><b>{active}</b></div><div className="topbar-actions"><span className="data-pill"><span /> AUTHENTICATED DATA</span><button className="top-user-btn" onClick={() => setShowAccountModal(true)} title="Account profile and settings" aria-label="Open user account profile"><div className="avatar avatar-teal avatar-small">{(auth.user.name ?? auth.user.email ?? "U").slice(0, 2).toUpperCase()}</div><span className="top-user-name">{auth.user.name ? auth.user.name.split(" ")[0] : auth.user.email?.split("@")[0]}</span></button><button className="icon-button notification-shortcut" onClick={() => open("Notifications")} aria-label={`Notifications, ${(notificationsQuery.data ?? []).filter((item) => !item.readAt).length} unread`}><Bell size={18} />{(notificationsQuery.data ?? []).some((item) => !item.readAt) && <span className="notification-dot" />}</button><button className="icon-button" onClick={() => notify("Permissions, workflow stages and data sources are controlled by the authenticated server.")} aria-label="Help"><CircleHelp size={18} /></button><button className="icon-button" onClick={() => open(permissions.has("inspection:view_assigned") || permissions.has("*") ? "Follow-up actions" : "Applications")} aria-label="Open pending work"><ShieldCheck size={18} /></button></div></header>
      <main className="main-content">{(recordsQuery.isLoading || applicationsQuery.isLoading) && <div className="notice-card" role="status"><ShieldCheck size={17} /><div>Loading workspace records…</div></div>}{(recordsQuery.error || applicationsQuery.error) && <Notice tone="warning"><b>Some workspace data could not be loaded.</b><p>{recordsQuery.error?.message ?? applicationsQuery.error?.message}</p><button className="button button-quiet" onClick={() => { void recordsQuery.refetch(); void applicationsQuery.refetch(); }}>Retry</button></Notice>}{active === "Notifications" && <NotificationsPage items={notificationsQuery.data ?? []} loading={notificationsQuery.isLoading} markRead={(id) => markNotificationRead.mutateAsync({ id })} markAllRead={() => markAllNotificationsRead.mutateAsync()} open={open} />}{active === "Overview" && <Overview records={records} applications={applications} open={open} inspections={inspectionsQuery.data ?? []} followUps={followUpsQuery.data ?? []} />}{active === "Borehole register" && <Register records={filtered} query={query} setQuery={setQuery} openRecord={setSelectedRecord} openCreate={() => setShowRecordForm(true)} canCreate={canCreateRecord} />}{active === "Applications" && <Applications applications={applications} records={records} workflow={workspace.data.settings.workflow} openCreate={() => { setApplicationCompleteness({}); setShowApplicationForm(true); }} canCreate={canCreateApplication} canReview={permissions.has("*") || permissions.has("application:review")} canDecide={permissions.has("*") || permissions.has("decision:record")} currentUserId={auth.user.id} transition={transition.mutateAsync} notify={notify} />}{active === "GIS screening" && <GIS workspace={workspace.data} records={records} canAssess={permissions.has("*") || permissions.has("screening:review")} assess={(id) => assessScreening.mutateAsync({ boreholeId: id })} notify={notify} />}{active === "Inspections" && <Inspections records={records} items={inspectionsQuery.data ?? []} inspectors={inspectorsQuery.data ?? []} currentUserId={auth.user.id} canAssign={permissions.has("*") || permissions.has("inspection:assign")} create={createInspection.mutateAsync} start={startInspection.mutateAsync} submit={submitInspection.mutateAsync} review={reviewInspection.mutateAsync} notify={notify} />}{active === "Follow-up actions" && <FollowUps items={followUpsQuery.data ?? []} inspections={inspectionsQuery.data ?? []} inspectors={inspectorsQuery.data ?? []} currentUserId={auth.user.id} canAssign={permissions.has("*") || permissions.has("inspection:assign")} create={createFollowUp.mutateAsync} update={updateFollowUp.mutateAsync} notify={notify} />}{active === "Reports" && <Reports records={records} notify={notify} />}{active === "Administration" && (auth.user.role === "admin" || permissions.has("layer:configure") || permissions.has("workflow:configure") || permissions.has("audit:view")) && <Administration workspace={workspace.data} authority={authority} setAuthority={setAuthority} notify={notify} users={usersQuery.data ?? []} assignRole={assignRole.mutateAsync} removeRole={removeRole.mutateAsync} canManageUsers={auth.user.role === "admin"} canConfigureLayers={auth.user.role === "admin" || permissions.has("layer:configure")} canManageSettings={auth.user.role === "admin" || permissions.has("workflow:configure")} canAudit={auth.user.role === "admin" || permissions.has("audit:view")} />}</main><footer className="footer-note"><span>BOREWATCH <i>·</i> AUTHENTICATED APPLICATION</span><span>Public information: {settings.publicHosting} <i>·</i> Records: {settings.privateHosting}</span></footer></div>
    {selectedRecord && <RecordDrawer record={selectedRecord} close={() => setSelectedRecord(null)} canUpload={permissions.has("*") || permissions.has("record:update")} canEdit={permissions.has("*") || permissions.has("record:update")} canViewParty={permissions.has("*") || permissions.has("party:view")} currentUserId={auth.user.id} onUpdate={(record) => setSelectedRecord(record)} update={updateRecord.mutateAsync} notify={notify} />}
    {showRecordForm && <Modal title="Create borehole record" close={() => setShowRecordForm(false)}><form onSubmit={saveRecord}><p className="dialog-intro">Use synthetic demonstration contact details unless collection has been authorized. Responsible-party contact data is stored separately and only visible to the record creator and users with the party-view permission.</p><label>Site name<input value={siteName} onChange={(event) => setSiteName(event.target.value)} required /></label><label>District / area<input value={district} onChange={(event) => setDistrict(event.target.value)} required /></label><label>Purpose<input value={purpose} onChange={(event) => setPurpose(event.target.value)} required maxLength={160} /></label><fieldset className="checklist"><legend>Responsible party</legend><label>Name<input required value={partyName} onChange={(event) => setPartyName(event.target.value)} maxLength={255} /></label><label>Organization<input value={partyOrganization} onChange={(event) => setPartyOrganization(event.target.value)} maxLength={255} /></label><label>Contact email<input type="email" value={partyEmail} onChange={(event) => setPartyEmail(event.target.value)} maxLength={320} /></label><label>Contact phone<input type="tel" value={partyPhone} onChange={(event) => setPartyPhone(event.target.value)} maxLength={64} /></label></fieldset><label>Location description<input value={locationDescription} onChange={(event) => setLocationDescription(event.target.value)} maxLength={1000} /></label><div className="coordinate-fields"><label>Latitude<input value={latitude} onChange={(event) => setLatitude(event.target.value)} required /></label><label>Longitude<input value={longitude} onChange={(event) => setLongitude(event.target.value)} required /></label></div><label>Coordinate reference system<input value="EPSG:4326 · WGS84" readOnly /></label><label>Estimated coordinate accuracy (m)<input type="number" min="0" step="0.1" value={coordinateAccuracy} onChange={(event) => setCoordinateAccuracy(event.target.value)} /></label><label>Coordinate capture date<input type="date" value={coordinateCapturedDate} onChange={(event) => setCoordinateCapturedDate(event.target.value)} /></label><label>Total depth (m)<input type="number" min="0" step="0.1" value={wellDepth} onChange={(event) => setWellDepth(event.target.value)} /></label><label>Construction notes<textarea value={constructionNotes} onChange={(event) => setConstructionNotes(event.target.value)} maxLength={500} /></label><div className="dialog-actions"><button type="button" className="button button-quiet" onClick={() => setShowRecordForm(false)}>Cancel</button><button className="button button-primary" disabled={createRecord.isPending}><Check size={15} /> Save record</button></div></form></Modal>}
    {showApplicationForm && <Modal title="Create application draft" close={() => setShowApplicationForm(false)}><form onSubmit={saveApplication}><p className="dialog-intro">Draft checklist progress is saved with the application. Final requirements and workflow stages require authority validation.</p><label>Application type<select value={applicationType} onChange={(event) => setApplicationType(event.target.value)}><option value="borehole_registration">Borehole registration</option><option value="drilling_authorization">Drilling authorization request</option><option value="completion_notice">Completion notice</option><option value="decommissioning">Decommissioning notice</option></select></label><label>Related borehole (optional)<select value={applicationBoreholeId} onChange={(event) => setApplicationBoreholeId(event.target.value)}><option value="">No existing borehole linked</option>{records.map((record) => <option key={record.id} value={record.id}>{record.recordCode} · {record.siteName}</option>)}</select></label><label>Local Sub-Catchment Council<input value={authority} onChange={(event) => setAuthority(event.target.value)} /></label><fieldset className="checklist"><legend>Supporting document checklist</legend>{[["site_plan", "Site plan / location sketch"], ["land_authority", "Proof of land access or authority"], ["technical_details", "Technical borehole details"], ["supporting_documents", "Other supporting documents"]].map(([key, label]) => <label key={key}><input type="checkbox" checked={Boolean(applicationCompleteness[key])} onChange={(event) => setApplicationCompleteness({ ...applicationCompleteness, [key]: event.target.checked })} />{label}</label>)}</fieldset><div className="dialog-actions"><button type="button" className="button button-quiet" onClick={() => setShowApplicationForm(false)}>Cancel</button><button className="button button-primary" disabled={createApplication.isPending}><Check size={15} /> Save draft</button></div></form></Modal>}
    {showAccountModal && <AccountDialog auth={auth} permissions={workspace.data.permissions} close={() => setShowAccountModal(false)} notify={notify} />}
    {toast && <div className="toast" role="status">{toast}</div>}
  </div>;
}

type NotificationItem = { id: number; type: string; title: string; message: string; entityType: string | null; entityId: number | null; readAt: Date | null; createdAt: Date };
function NotificationsPage({ items, loading, markRead, markAllRead, open }: { items: NotificationItem[]; loading: boolean; markRead: (id: number) => Promise<unknown>; markAllRead: () => Promise<unknown>; open: (section: Section) => void }) { const unread = items.filter((item) => !item.readAt); const openTarget = (item: NotificationItem) => { void markRead(item.id); open(item.entityType === "inspection" ? "Inspections" : item.entityType === "follow_up" ? "Follow-up actions" : "Applications"); }; return <><TitleBlock eyebrow="IN-APP ALERTS" title="Notifications" detail="Status changes and assignments for your account." action={unread.length > 0 ? <button className="button button-quiet" onClick={() => void markAllRead()}>Mark all read</button> : undefined} />{loading ? <div className="panel">Loading notifications…</div> : <div className="panel notification-list">{items.map((item) => <article className={`notification-row ${item.readAt ? "read" : "unread"}`} key={item.id}><div className="notification-icon"><Bell size={16} /></div><div className="notification-copy"><b>{item.title}</b><p>{item.message}</p><small>{new Date(item.createdAt).toLocaleString()}</small></div>{!item.readAt && <Badge tone="amber">New</Badge>}<button className="button button-quiet" onClick={() => openTarget(item)}>{item.entityId ? "Open" : "Mark read"}</button></article>)}{items.length === 0 && <div className="empty-state"><Bell size={22} /><b>You’re all caught up</b><span>Application, inspection and follow-up updates will appear here.</span></div>}</div>}</>; }

function Overview({ records, applications, open, inspections, followUps }: { records: RecordView[]; applications: Array<{ stage: string }>; open: (section: Section) => void; inspections: Array<{ status: string; dueAt: Date | null }>; followUps: Array<{ status: string; dueAt: Date | null }> }) { const pendingInspections = inspections.filter((item) => item.status !== "submitted").length; const overdueActions = [...inspections, ...followUps].filter((item) => item.status !== "submitted" && item.status !== "completed" && item.dueAt && new Date(item.dueAt).getTime() < Date.now()).length; return <><TitleBlock eyebrow="SERVER-BACKED WORKSPACE" title="Overview" detail="Current counts and work queues from the authenticated project database." action={<button className="button button-primary" onClick={() => open("Borehole register")}><Database size={15} /> View records</button>} /><Notice><b>{records.length} borehole records loaded from the project database.</b><p>Operational status, application stage, inspection findings and screening assessment remain separate.</p></Notice><section className="metric-row"><Metric label="Borehole records" value={String(records.length)} /><Metric label="Applications" value={String(applications.length)} /><Metric label="Under review" value={String(applications.filter((item) => item.stage === "under_review").length)} /><Metric label="Unable to assess" value={String(records.filter((record) => record.screeningStatus === "unable_to_assess").length)} /></section><div className="queue-grid"><button className="panel queue-link" onClick={() => open("Inspections")}><span className="eyebrow">FIELD WORK</span><b>{pendingInspections} inspection(s) awaiting submission</b><span>Open inspector worklist <ArrowRight size={13} /></span></button><button className="panel queue-link" onClick={() => open("Follow-up actions")}><span className="eyebrow">FOLLOW-UP</span><b>{overdueActions} overdue action(s)</b><span>Review assignments and due dates <ArrowRight size={13} /></span></button><button className="panel queue-link" onClick={() => open("Applications")}><span className="eyebrow">APPLICATIONS</span><b>{applications.filter((item) => ["submitted", "under_review", "information_requested"].includes(item.stage)).length} application(s) need review</b><span>Open application queue <ArrowRight size={13} /></span></button></div><div className="panel"><div className="panel-head"><div><span className="eyebrow">ACCESS AND GOVERNANCE</span><h2>Protected operational data</h2></div><Badge tone="mint">Authenticated</Badge></div><p className="dialog-intro">The system does not fabricate official decisions or claim hazard absence. Missing verified spatial sources are explicitly marked “Unable to assess.”</p></div></>; }
function Metric({ label, value }: { label: string; value: string }) { return <div className="metric-card"><div className="metric-top"><span>{label}</span><span className="metric-icon metric-teal"><Database size={16} /></span></div><div className="metric-value">{value}</div><div className="metric-change">Database result</div></div>; }
function Register({ records, query, setQuery, openRecord, openCreate, canCreate }: { records: RecordView[]; query: string; setQuery: (value: string) => void; openRecord: (record: RecordView) => void; openCreate: () => void; canCreate: boolean }) { return <><TitleBlock eyebrow="DATABASE RECORDS" title="Borehole register" detail="Search and maintain records stored on the protected project database." action={canCreate ? <button className="button button-primary" onClick={openCreate}><Plus size={15} /> New record</button> : undefined} /><div className="panel register-view"><div className="register-toolbar"><div className="search-field"><Search size={16} /><input aria-label="Search borehole records" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search server records…" /></div><span className="register-count" aria-live="polite">{records.length} matching records</span></div><div className="table-wrap"><table><thead><tr><th>RECORD</th><th>AREA</th><th>PURPOSE</th><th>OPERATIONAL STATUS</th><th>APPLICATION</th><th>SCREENING</th><th /></tr></thead><tbody>{records.map((record) => <tr key={record.id} onClick={() => openRecord(record)} tabIndex={0} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); openRecord(record); } }} aria-label={`Open ${record.siteName}`}><td><div className="record-cell"><div className="record-avatar">{record.siteName.slice(0, 2).toUpperCase()}</div><span><b>{record.siteName}</b><small>{record.recordCode}</small></span></div></td><td>{record.district}</td><td>{record.purpose}</td><td><Badge>{record.operationalStatus}</Badge></td><td>{record.applicationStatus}</td><td>{record.screeningStatus}</td><td><ChevronRight size={15} /></td></tr>)}</tbody></table>{records.length === 0 && <div className="empty-state"><Database size={22} /><b>No records match this search</b><span>Try another site name, reference, area or purpose.</span></div>}</div></div></>; }
type ApplicationView = { id: number; reference: string; stage: string; boreholeId: number | null; applicantId: number; updatedAt: Date; applicationType: string; completenessJson: string | null; decisionOutcome: string | null; decisionConditions: string | null };
const requiredApplicationDocuments = ["site_plan", "land_authority", "technical_details", "supporting_documents"] as const;
function Applications({ applications, records, workflow, openCreate, canCreate, canReview, canDecide, currentUserId, transition, notify }: { applications: ApplicationView[]; records: RecordView[]; workflow: unknown; openCreate: () => void; canCreate: boolean; canReview: boolean; canDecide: boolean; currentUserId: number; transition: (input: { applicationId: number; toStage: string; reason?: string; decisionOutcome?: "approved" | "rejected" | "withdrawn"; decisionConditions?: string }) => Promise<unknown>; notify: (message: string) => void }) {
  const stages = (workflow as { stages?: Array<{ key: string; label: string; allowedNext: string[] }> }).stages ?? [];
  return <><TitleBlock eyebrow="APPLICATION WORKFLOW" title="Applications" detail="Draft intake, checklist and supporting evidence, configured review stages and traceable history." action={canCreate ? <button className="button button-primary" onClick={openCreate}><Plus size={15} /> New application</button> : undefined} /><Notice><b>Only an authorized human may record an outcome.</b><p>Application status does not itself grant legal authorization. Workflow stages are configurable and pending authority validation.</p></Notice><div className="panel application-list">{applications.map((application) => <ApplicationRow key={application.id} application={application} record={records.find((record) => record.id === application.boreholeId)} stages={stages} canReview={canReview} canDecide={canDecide} currentUserId={currentUserId} transition={transition} notify={notify} />)}{applications.length === 0 && <div className="empty-state"><FileCheck2 size={22} /><b>No applications available</b><span>Authorized applicants can create and track their drafts here.</span></div>}</div></>;
}
function ApplicationRow({ application, record, stages, canReview, canDecide, currentUserId, transition, notify }: { application: ApplicationView; record?: RecordView; stages: Array<{ key: string; label: string; allowedNext: string[] }>; canReview: boolean; canDecide: boolean; currentUserId: number; transition: (input: { applicationId: number; toStage: string; reason?: string; decisionOutcome?: "approved" | "rejected" | "withdrawn"; decisionConditions?: string }) => Promise<unknown>; notify: (message: string) => void }) {
  const [nextStage, setNextStage] = useState(""); const [reason, setReason] = useState(""); const [outcome, setOutcome] = useState<"approved" | "rejected" | "withdrawn">("approved"); const [conditions, setConditions] = useState("");
  let initial: Record<string, boolean> = {}; try { initial = JSON.parse(application.completenessJson ?? "{}") as Record<string, boolean>; } catch { initial = {}; }
  const [checklist, setChecklist] = useState<Record<string, boolean>>(initial); const [applicationType, setApplicationType] = useState(application.applicationType);
  const updateDraft = trpc.borewatch.applications.updateDraft.useMutation({ onSuccess: () => notify("Application draft and checklist saved."), onError: (error) => notify(error.message) });
  const evidence = trpc.borewatch.evidence.list.useQuery({ entityType: "application", entityId: application.id });
  const uploaded = new Set((evidence.data ?? []).map((file) => file.documentType).filter(Boolean));
  const stageName = (key: string) => stages.find((stage) => stage.key === key)?.label ?? key.replaceAll("_", " ");
  const allAllowed = stages.find((stage) => stage.key === application.stage)?.allowedNext ?? []; const allowed = allAllowed.filter((key) => key !== "decision_recorded" || canDecide);
  const ownsDraft = application.applicantId === currentUserId && application.stage === "draft";
  const canRespond = application.applicantId === currentUserId && application.stage === "information_requested" && allowed.includes("under_review"); const canMove = canReview || ownsDraft || canRespond;
  return <article className="application-card"><div className="application-heading"><div><span className="eyebrow">{application.reference} · {application.applicationType.replaceAll("_", " ")}</span><h2>{record?.siteName ?? "Unlinked application"}</h2><small>{record?.recordCode ?? "No borehole linked"} · Updated {new Date(application.updatedAt).toLocaleString()}</small></div><Badge tone={application.decisionOutcome ? "mint" : "blue"}>{stageName(application.stage)}{application.decisionOutcome ? ` · ${application.decisionOutcome}` : ""}</Badge></div>
    <details className="application-details"><summary>Application details, evidence and history</summary>{ownsDraft && <section className="draft-checklist"><h3>Submission checklist</h3><label>Application type<select value={applicationType} onChange={(event) => setApplicationType(event.target.value)}><option value="borehole_registration">Borehole registration</option><option value="drilling_authorization">Drilling authorization request</option><option value="completion_notice">Completion notice</option><option value="decommissioning">Decommissioning notice</option></select></label>{requiredApplicationDocuments.map((key) => <label className="checkline" key={key}><input type="checkbox" checked={Boolean(checklist[key])} onChange={(event) => setChecklist({ ...checklist, [key]: event.target.checked })} />{key.replaceAll("_", " ")} attached and ready for review {uploaded.has(key) ? "✓ uploaded" : "· file not uploaded"}</label>)}<button className="button button-quiet" disabled={updateDraft.isPending} onClick={() => updateDraft.mutate({ applicationId: application.id, applicationType, completeness: checklist })}>Save draft checklist</button></section>}
      <EvidencePanel entityType="application" entityId={application.id} canUpload={ownsDraft || canRespond || canReview} showDocumentType />
      {allowed.length > 0 && canMove && <section className="transition-box"><h3>Available workflow transitions</h3><label>Next stage<select value={nextStage} onChange={(event) => setNextStage(event.target.value)}><option value="">Select configured next stage</option>{allowed.map((key) => <option key={key} value={key}>{stageName(key)}</option>)}</select></label>{(nextStage === "information_requested" || nextStage === "decision_recorded" || canRespond && nextStage === "under_review") && <label>Reason<textarea required maxLength={2000} value={reason} onChange={(event) => setReason(event.target.value)} /></label>}{nextStage === "decision_recorded" && <><label>Human decision outcome<select value={outcome} onChange={(event) => setOutcome(event.target.value as typeof outcome)}><option value="approved">Approved</option><option value="rejected">Rejected</option><option value="withdrawn">Withdrawn</option></select></label><label>Conditions<textarea maxLength={4000} value={conditions} onChange={(event) => setConditions(event.target.value)} /></label></>}<button className="button button-primary" disabled={!nextStage || (nextStage === "submitted" && requiredApplicationDocuments.some((key) => !checklist[key] || !uploaded.has(key))) || ((nextStage === "information_requested" || nextStage === "decision_recorded" || canRespond && nextStage === "under_review") && !reason.trim())} onClick={async () => { if (!nextStage || !window.confirm(`Record ${stageName(nextStage)} for ${application.reference}?`)) return; try { await transition({ applicationId: application.id, toStage: nextStage, reason: reason || undefined, decisionOutcome: nextStage === "decision_recorded" ? outcome : undefined, decisionConditions: conditions || undefined }); notify("Application transition recorded with audit history."); setNextStage(""); } catch (error) { notify(error instanceof Error ? error.message : "Transition rejected"); } }}>Confirm transition</button></section>}
      <ApplicationHistory applicationId={application.id} stages={stages} />
    </details></article>;
}
function ApplicationHistory({ applicationId, stages }: { applicationId: number; stages: Array<{ key: string; label: string }> }) { const history = trpc.borewatch.applications.history.useQuery({ applicationId }); const label = (key: string | null) => key ? stages.find((stage) => stage.key === key)?.label ?? key : "Created"; return <section className="history-box"><h3>Workflow history · read only</h3>{history.isLoading ? <p>Loading history…</p> : history.error ? <p>{history.error.message}</p> : history.data?.length ? history.data.map((item) => <div className="history-entry" key={item.id}><b>{label(item.fromStage)} → {label(item.toStage)}</b><time>{new Date(item.createdAt).toLocaleString()}</time>{item.reason && <p>{item.reason}</p>}</div>) : <p>No transitions recorded yet.</p>}</section>; }

function GeoLayerOverlay({ layer }: { layer: WorkspaceData["layers"][number] }) {
  if (!layer.geometryJson) return null;
  const paths: string[] = []; const points: Array<[number, number]> = [];
  const project = (position: number[]) => [260 + (position[0] - 25) * 60, 70 + (-15 - position[1]) * 53.75];
  const line = (positions: number[][], close = false) => { if (!positions.length) return; const coords = positions.map(project); paths.push(`M ${coords.map((p) => `${p[0]} ${p[1]}`).join(" L ")}${close ? " Z" : ""}`); };
  const visit = (geometry: any) => { if (!geometry) return; const c = geometry.coordinates; switch (geometry.type) { case "Point": points.push(project(c) as [number, number]); break; case "MultiPoint": for (const p of c) points.push(project(p) as [number, number]); break; case "LineString": line(c); break; case "MultiLineString": for (const l of c) line(l); break; case "Polygon": for (const ring of c) line(ring, true); break; case "MultiPolygon": for (const polygon of c) for (const ring of polygon) line(ring, true); break; case "GeometryCollection": for (const item of geometry.geometries ?? []) visit(item); break; } };
  try { const data = JSON.parse(layer.geometryJson) as any; if (data.type === "FeatureCollection") data.features.forEach((feature: any) => visit(feature.geometry)); else visit(data.type === "Feature" ? data.geometry : data); } catch { return null; }
  return <g className="hazard-layer" aria-label={`${layer.name} · ${layer.verificationStatus}`}>{paths.map((d, index) => <path key={`${layer.layerKey}-path-${index}`} d={d} />)}{points.map(([cx, cy], index) => <circle key={`${layer.layerKey}-point-${index}`} cx={cx} cy={cy} r="8" />)}<title>{layer.name} · {layer.version} · {layer.verificationStatus}</title></g>;
}

function GIS({ workspace, records, canAssess, assess, notify }: { workspace: WorkspaceData; records: RecordView[]; canAssess: boolean; assess: (id: number) => Promise<unknown>; notify: (message: string) => void }) { const [district, setDistrict] = useState("all"); const [status, setStatus] = useState("all"); const [selected, setSelected] = useState<RecordView | null>(null); const screeningHistory = trpc.borewatch.screening.history.useQuery({ boreholeId: selected?.id ?? 0 }, { enabled: Boolean(selected) }); const areas = [...new Set(records.map((record) => record.district))].sort(); const visible = records.filter((record) => (district === "all" || record.district === district) && (status === "all" || record.operationalStatus === status)); const statuses = [...new Set(records.map((record) => record.operationalStatus))].sort(); const bounds = { west: 25, east: 33, south: -23, north: -15 }; const inBounds = visible.filter((record) => Number(record.longitude) >= bounds.west && Number(record.longitude) <= bounds.east && Number(record.latitude) >= bounds.south && Number(record.latitude) <= bounds.north); const point = (record: RecordView) => ({ x: 260 + (Number(record.longitude) - bounds.west) * 60, y: 70 + (bounds.north - Number(record.latitude)) * 53.75 }); return <><TitleBlock eyebrow="MAP AND SOURCE METADATA" title="GIS screening" detail="Borehole coordinates and authorized GeoJSON hazard layers on a longitude/latitude grid." /><Notice><b>Preliminary screening requires human review.</b><p>Only active rules backed by verified WGS84 layers and verified sources are calculated. Missing or stale inputs return “unable to assess”; a rule match is not proof of contamination, non-compliance or safety.</p></Notice><div className="gis-layout"><div className="panel gis-map-panel"><div className="panel-head"><div><span className="eyebrow">REGISTER LOCATIONS</span><h2>{inBounds.length} mapped · {visible.length - inBounds.length} outside view</h2></div><label className="filter-select">Area<select value={district} onChange={(event) => setDistrict(event.target.value)}><option value="all">All areas</option>{areas.map((area) => <option key={area}>{area}</option>)}</select></label><label className="filter-select">Operational status<select value={status} onChange={(event) => setStatus(event.target.value)}><option value="all">All statuses</option>{statuses.map((item) => <option key={item}>{item}</option>)}</select></label></div><svg className="coordinate-map" viewBox="0 0 1000 560" role="group" aria-label="Geographic grid showing borehole and authorized hazard-layer features within the Zimbabwe plotting extent"><rect width="1000" height="560" rx="8" fill="#f5f7f1" />{Array.from({ length: 9 }, (_, i) => <g key={i}><line x1={260 + i * 60} y1="70" x2={260 + i * 60} y2="500" stroke="#dce5dc" /><line x1="260" y1={70 + i * 53.75} x2="740" y2={70 + i * 53.75} stroke="#dce5dc" /><text x={260 + i * 53.333} y="525" textAnchor="middle">{(25 + i).toFixed(1)}°E</text><text x="250" y={74 + i * 53.75} textAnchor="end">{(-15 - i).toFixed(1)}°</text></g>)}<text x="500" y="35" textAnchor="middle">DECIMAL DEGREE GRID · APPROXIMATE NATIONAL EXTENT</text>{workspace.layers.filter((layer) => layer.active && layer.geometryJson).map((layer) => <GeoLayerOverlay key={layer.layerKey} layer={layer} />)}{inBounds.map((record) => { const p = point(record); return <g key={record.id} role="button" tabIndex={0} aria-label={`Select ${record.recordCode}, ${record.siteName}`} onClick={() => setSelected(record)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); setSelected(record); } }} className="map-marker"><circle cx={p.x} cy={p.y} r="11" /><circle cx={p.x} cy={p.y} r="4" /><title>{record.recordCode} · {record.siteName} · {record.latitude}, {record.longitude}</title></g>; })}</svg><div className="map-legend"><span><i className="legend-marker" /> Borehole record</span><span><i className="legend-hazard" /> Authorized spatial layer</span><span>Coordinates: decimal degrees · bounds only, not positional accuracy</span></div></div><div className="gis-side"><div className="panel"><div className="panel-head"><div><span className="eyebrow">SELECTED SITE</span><h2>{selected?.siteName ?? "Choose a map marker"}</h2></div><MapPin size={17} /></div>{selected ? <><p>{selected.recordCode} · {selected.district}</p><code>{selected.latitude}, {selected.longitude}</code><p><Badge tone="amber">Unable to assess</Badge></p>{canAssess && <button className="button button-quiet" onClick={async () => { try { const results = await assess(selected.id); notify(`Screening assessment saved (${Array.isArray(results) ? results.length : 0} rule result(s)).`); } catch (error) { notify(error instanceof Error ? error.message : "Assessment failed"); } }}>Run configured screening</button>}{screeningHistory.data?.length ? <div className="history-box"><h3>Assessment history</h3>{screeningHistory.data.map((result) => <div className="history-entry" key={result.id}><b>{result.outcome.replaceAll("_", " ")} · {new Date(result.assessedAt).toLocaleString()}</b><small>Rule: {result.ruleKey ?? "none configured"} · Source: {result.sourceKey ?? "none available"}</small><p>{result.explanation}</p></div>)}</div> : null}</> : <p>Select a marker to view its record details and current screening state.</p>}</div><div className="panel"><div className="panel-head"><div><span className="eyebrow">CONFIGURED SOURCES</span><h2>Layer availability</h2></div><Layers3 size={17} /></div><div className="layer-panel">{workspace.sources.map((source) => <div className="source-card" key={source.sourceKey}><div className="source-status"><b>{source.name}</b><Badge tone="amber">{source.accessStatus.toLowerCase().includes("await") ? "Unavailable" : source.accessLevel}</Badge></div><p className="source-purpose">{source.purpose}</p><small>{source.accessStatus}</small>{source.metadataJson && <small className="source-metadata">Metadata: {source.metadataJson}</small>}</div>)}</div></div><div className="panel"><div className="panel-head"><div><span className="eyebrow">SCREENING RULES</span><h2>{workspace.rules.length} configured</h2></div></div>{workspace.rules.length ? workspace.rules.map((rule) => <div className="source-card" key={`${rule.ruleKey}@${rule.version}`}><b>{rule.name} · v{rule.version}</b><p>{rule.explanation}</p><small>{rule.jurisdiction} · {rule.hazardType} · {rule.sourceKey} · {rule.active ? "Active" : "Inactive pending review"}</small></div>) : <p>No rules are configured. No rule is assumed.</p>}</div></div></div></>; }

type InspectionView = { id: number; reference: string; boreholeId: number; assignedTo: number; dueAt: Date | null; status: string; checklistJson: string; coordinatesConfirmed: boolean; observations: string | null; findings: string | null; recommendations: string | null; submittedAt: Date | null; reviewedBy: number | null; reviewedAt: Date | null; reviewNotes: string | null };
type FollowUpView = { id: number; inspectionId: number; boreholeId: number; title: string; ownerId: number; dueAt: Date | null; status: string };
type InspectorUser = { id: number; name: string | null; email: string };
function Inspections({ records, items, inspectors, currentUserId, canAssign, create, start, submit, review, notify }: { records: RecordView[]; items: InspectionView[]; inspectors: InspectorUser[]; currentUserId: number; canAssign: boolean; create: (input: { boreholeId: number; assignedTo: number; dueAt?: string }) => Promise<unknown>; start: (input: { inspectionId: number }) => Promise<unknown>; submit: (input: { inspectionId: number; coordinatesConfirmed: true; checklist: Record<string, boolean>; observations: string; findings: string; recommendations?: string }) => Promise<unknown>; review: (input: { inspectionId: number; outcome: "reviewed" | "follow_up_required"; notes?: string }) => Promise<unknown>; notify: (message: string) => void }) {
  const [recordId, setRecordId] = useState(""); const [assignedTo, setAssignedTo] = useState(String(currentUserId)); const [due, setDue] = useState("");
  return <><TitleBlock eyebrow="FIELD WORK" title="Inspections" detail="Assigned site checks and immutable submitted findings. Capture is responsive for mobile browsers; offline sync is not provided." action={canAssign ? <button className="button button-primary" onClick={() => document.getElementById("inspection-assign-form")?.scrollIntoView({ behavior: "smooth" })}><Plus size={15} /> Assign inspection</button> : undefined} /><Notice><b>Submitted findings are retained as history.</b><p>Coordinate confirmation and inspection notes record field observations; they are not laboratory results or regulatory decisions.</p></Notice>
    {canAssign && <form className="panel inline-form" id="inspection-assign-form" onSubmit={async (event) => { event.preventDefault(); if (!recordId || !assignedTo) return; try { await create({ boreholeId: Number(recordId), assignedTo: Number(assignedTo), dueAt: due ? new Date(`${due}T23:59:59`).toISOString() : undefined }); notify("Inspection assigned."); } catch (error) { notify(error instanceof Error ? error.message : "Unable to assign inspection"); } }}><label>Borehole<select required value={recordId} onChange={(event) => setRecordId(event.target.value)}><option value="">Choose a borehole</option>{records.map((record) => <option key={record.id} value={record.id}>{record.recordCode} · {record.siteName}</option>)}</select></label><label>Assigned inspector<select required value={assignedTo} onChange={(event) => setAssignedTo(event.target.value)}>{inspectors.map((inspector) => <option value={inspector.id} key={inspector.id}>{inspector.name ?? inspector.email}</option>)}</select></label><label>Due date<input type="date" value={due} onChange={(event) => setDue(event.target.value)} /></label><button className="button button-primary" disabled={inspectors.length === 0}>Create assignment</button></form>}
    <div className="inspection-list">{items.map((item) => <InspectionCard key={item.id} item={item} record={records.find((record) => record.id === item.boreholeId)} canSubmit={item.assignedTo === currentUserId} canReview={canAssign} start={start} submit={submit} review={review} notify={notify} />)}{items.length === 0 && <div className="panel empty-state"><b>No assigned inspections</b><span>Inspection assignments for your account will appear here.</span></div>}</div></>;
}
function InspectionCard({ item, record, canSubmit, canReview, start, submit, review, notify }: { item: InspectionView; record?: RecordView; canSubmit: boolean; canReview: boolean; start: (input: { inspectionId: number }) => Promise<unknown>; submit: (input: { inspectionId: number; coordinatesConfirmed: true; checklist: Record<string, boolean>; observations: string; findings: string; recommendations?: string }) => Promise<unknown>; review: (input: { inspectionId: number; outcome: "reviewed" | "follow_up_required"; notes?: string }) => Promise<unknown>; notify: (message: string) => void }) {
  const [confirmed, setConfirmed] = useState(false); const [checklist, setChecklist] = useState<Record<string, boolean>>({ siteIdentityConfirmed: false, accessAndConditionObserved: false, evidenceRecorded: false }); const [observations, setObservations] = useState(""); const [findings, setFindings] = useState(""); const [recommendations, setRecommendations] = useState(""); const [reviewOutcome, setReviewOutcome] = useState<"reviewed" | "follow_up_required">("reviewed"); const [reviewNotes, setReviewNotes] = useState("");
  return <article className="panel inspection-card"><div className="panel-head"><div><span className="eyebrow">{item.reference}</span><h2>{record?.siteName ?? "Borehole record"}</h2></div><Badge tone={item.status === "reviewed" ? "mint" : item.status === "follow_up_required" ? "amber" : "blue"}>{item.status.replaceAll("_", " ")}</Badge></div><p>{record?.recordCode} · {record?.district} · Due {item.dueAt ? new Date(item.dueAt).toLocaleDateString() : "Not set"}</p><p className="coordinates">Recorded coordinates: {record?.latitude}, {record?.longitude}</p><EvidencePanel entityType="inspection" entityId={item.id} canUpload={canSubmit && !item.submittedAt} />
    {!item.submittedAt && canSubmit && item.status === "assigned" && <button className="button button-primary" onClick={async () => { try { await start({ inspectionId: item.id }); notify("Inspection started. Confirm coordinates and complete the field form."); } catch (error) { notify(error instanceof Error ? error.message : "Unable to start inspection"); } }}>Start inspection</button>}
    {item.submittedAt ? <div className="finding-history"><b>Submitted {new Date(item.submittedAt).toLocaleString()}</b><p><strong>Observations:</strong> {item.observations}</p><p><strong>Findings:</strong> {item.findings}</p>{item.recommendations && <p><strong>Recommendations:</strong> {item.recommendations}</p>}{item.reviewedAt && <p><strong>Review:</strong> {item.status.replaceAll("_", " ")} · {new Date(item.reviewedAt).toLocaleString()} · {item.reviewNotes ?? "No review note"}</p>}</div> : canSubmit && item.status === "in_progress" && <form className="inspection-form" onSubmit={async (event) => { event.preventDefault(); try { await submit({ inspectionId: item.id, coordinatesConfirmed: true, checklist, observations, findings, recommendations: recommendations || undefined }); notify("Inspection findings submitted and retained."); } catch (error) { notify(error instanceof Error ? error.message : "Unable to submit findings"); } }}><label className="checkline"><input type="checkbox" required checked={confirmed} onChange={(event) => setConfirmed(event.target.checked)} /> I confirmed the displayed coordinates at the site.</label>{Object.entries({ siteIdentityConfirmed: "Site identity checked", accessAndConditionObserved: "Access and physical condition observed", evidenceRecorded: "Evidence captured or noted" }).map(([key, label]) => <label className="checkline" key={key}><input type="checkbox" checked={Boolean(checklist[key])} onChange={(event) => setChecklist({ ...checklist, [key]: event.target.checked })} />{label}</label>)}<label>Observations<textarea required maxLength={10000} value={observations} onChange={(event) => setObservations(event.target.value)} /></label><label>Findings<textarea required maxLength={10000} value={findings} onChange={(event) => setFindings(event.target.value)} /></label><label>Recommendations<textarea maxLength={10000} value={recommendations} onChange={(event) => setRecommendations(event.target.value)} /></label><button className="button button-primary" disabled={!confirmed}>Submit inspection report</button></form>}
    {item.submittedAt && item.status === "submitted" && canReview && <form className="inspection-form" onSubmit={async (event) => { event.preventDefault(); try { await review({ inspectionId: item.id, outcome: reviewOutcome, notes: reviewNotes || undefined }); notify(reviewOutcome === "follow_up_required" ? "Inspection review saved; create a follow-up action." : "Inspection review completed."); } catch (error) { notify(error instanceof Error ? error.message : "Unable to review inspection"); } }}><label>Review outcome<select value={reviewOutcome} onChange={(event) => setReviewOutcome(event.target.value as typeof reviewOutcome)}><option value="reviewed">Reviewed</option><option value="follow_up_required">Follow-up required</option></select></label><label>Review notes{reviewOutcome === "follow_up_required" && " (required)"}<textarea required={reviewOutcome === "follow_up_required"} maxLength={4000} value={reviewNotes} onChange={(event) => setReviewNotes(event.target.value)} /></label><button className="button button-quiet">Save review</button></form>}
  </article>;
}
function FollowUps({ items, inspections, inspectors, currentUserId, canAssign, create, update, notify }: { items: FollowUpView[]; inspections: InspectionView[]; inspectors: InspectorUser[]; currentUserId: number; canAssign: boolean; create: (input: { inspectionId: number; title: string; ownerId: number; dueAt?: string }) => Promise<unknown>; update: (input: { id: number; status: "open" | "in_progress" | "completed" | "cancelled" }) => Promise<unknown>; notify: (message: string) => void }) {
  const [inspectionId, setInspectionId] = useState(""); const [title, setTitle] = useState(""); const [due, setDue] = useState(""); const [ownerId, setOwnerId] = useState(String(currentUserId));
  const submitted = inspections.filter((item) => item.submittedAt && item.status === "follow_up_required");
  return <><TitleBlock eyebrow="FOLLOW-UP QUEUE" title="Follow-up actions" detail="Actions linked to submitted inspection findings, with an owner and due date." />
    {canAssign && <form className="panel inline-form" onSubmit={async (event) => { event.preventDefault(); if (!inspectionId || !title.trim()) return; try { await create({ inspectionId: Number(inspectionId), title, ownerId: Number(ownerId), dueAt: due ? new Date(`${due}T23:59:59`).toISOString() : undefined }); setTitle(""); setInspectionId(""); setDue(""); notify("Follow-up action assigned to your account."); } catch (error) { notify(error instanceof Error ? error.message : "Unable to create action"); } }}><label>Submitted inspection<select required value={inspectionId} onChange={(event) => setInspectionId(event.target.value)}><option value="">Choose a finding</option>{submitted.map((item) => <option key={item.id} value={item.id}>{item.reference} · borehole #{item.boreholeId}</option>)}</select></label><label>Action<textarea required maxLength={255} value={title} onChange={(event) => setTitle(event.target.value)} /></label><label>Owner<select value={ownerId} onChange={(event) => setOwnerId(event.target.value)}>{inspectors.map((inspector) => <option key={inspector.id} value={inspector.id}>{inspector.name ?? inspector.email}</option>)}</select></label><label>Due date<input type="date" value={due} onChange={(event) => setDue(event.target.value)} /></label><button className="button button-primary" disabled={!submitted.length}>Assign action</button></form>}
    <div className="panel followup-list">{items.map((item) => <div className="followup-row" key={item.id}><div><b>{item.title}</b><small>Inspection #{item.inspectionId} · Borehole #{item.boreholeId} · Owner ID {item.ownerId}</small></div><span>{item.dueAt ? new Date(item.dueAt).toLocaleDateString() : "No due date"}</span><Badge tone={item.status === "completed" ? "mint" : "amber"}>{item.status.replaceAll("_", " ")}</Badge><select aria-label={`Update status for ${item.title}`} value={item.status} onChange={async (event) => { try { await update({ id: item.id, status: event.target.value as "open" | "in_progress" | "completed" | "cancelled" }); notify("Follow-up status updated."); } catch (error) { notify(error instanceof Error ? error.message : "Unable to update action"); } }}><option value="open">Open</option><option value="in_progress">In progress</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></div>)}{items.length === 0 && <div className="empty-state"><b>No follow-up actions</b><span>Actions will appear after an inspection report is submitted and a follow-up is assigned.</span></div>}</div></>;
}
function Reports({ records, notify }: { records: RecordView[]; notify: (message: string) => void }) {
  const [district, setDistrict] = useState(""); const [status, setStatus] = useState(""); const [from, setFrom] = useState(""); const [to, setTo] = useState(""); const [notes, setNotes] = useState("");
  const fromIso = from ? new Date(`${from}T00:00:00`).toISOString() : undefined; const toIso = to ? new Date(`${to}T23:59:59.999`).toISOString() : undefined;
  const report = trpc.borewatch.reports.boreholes.useQuery({ from: fromIso, to: toIso, district: district || undefined, operationalStatus: status || undefined });
  const logExport = trpc.borewatch.reports.logExport.useMutation(); const areas = [...new Set(records.map((record) => record.district))].sort();
  const columns = ["recordCode", "siteName", "district", "purpose", "latitude", "longitude", "operationalStatus", "applicationStatus", "screeningStatus", "createdAt"] as const;
  const auditExport = (exportFormat: "csv" | "pdf") => logExport.mutateAsync({ from: fromIso, to: toIso, district: district || undefined, operationalStatus: status || undefined, rowCount: report.data?.length ?? 0, notes: notes || undefined, exportFormat });
  const exportCsv = async () => { const rows = report.data ?? []; try { await auditExport("csv"); const escape = (value: unknown) => `"${String(value ?? "").replaceAll('"', '""')}"`; const csv = ["# BoreWatch report · authorized records", `# Notes: ${notes.replaceAll("\n", " ").replaceAll(",", ";")}`, columns.join(","), ...rows.map((row) => columns.map((column) => escape((row as unknown as Record<string, unknown>)[column])).join(","))].join("\r\n"); const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); link.download = "borewatch-authorized-register-report.csv"; link.click(); window.setTimeout(() => URL.revokeObjectURL(link.href), 1000); } catch (error) { notify(error instanceof Error ? error.message : "Report export could not be audited"); } };
  const exportPdf = async () => { const popup = window.open("about:blank", "_blank"); if (!popup) { notify("Allow pop-ups to print or save this report as PDF."); return; } popup.opener = null; try { await auditExport("pdf"); const rows = report.data ?? []; const esc = (value: unknown) => String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;"); const heading = ["Borehole register report", notes ? `Notes: ${notes}` : "Authorized records · BoreWatch"]; const table = `<table><thead><tr>${columns.map((column) => `<th>${esc(column.replace(/[A-Z]/g, (letter) => ` ${letter.toLowerCase()}`))}</th>`).join("")}</tr></thead><tbody>${rows.map((row) => `<tr>${columns.map((column) => `<td>${esc((row as unknown as Record<string, unknown>)[column])}</td>`).join("")}</tr>`).join("")}</tbody></table>`; popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>BoreWatch report</title><style>body{font:12px Arial,sans-serif;color:#17231d;padding:24px}h1{font-size:22px}p{color:#526158}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccd5cc;padding:6px;text-align:left;word-break:break-word}th{background:#edf2eb;font-size:10px;text-transform:uppercase}@media print{body{padding:0}tr{break-inside:avoid}thead{display:table-header-group}}</style></head><body><h1>${esc(heading[0])}</h1><p>${esc(heading[1])}</p><p>${rows.length} record(s) · Generated ${esc(new Date().toLocaleString())} · Preliminary administrative report; not a compliance certificate.</p>${table}</body></html>`); popup.document.close(); popup.focus(); window.setTimeout(() => popup.print(), 400); } catch (error) { popup.close(); notify(error instanceof Error ? error.message : "PDF export could not be audited"); } };
  const disabled = report.isLoading || report.isError || !report.data || logExport.isPending;
  return <><TitleBlock eyebrow="AUTHORIZED REPORTING" title="Reports" detail="Filter permitted borehole records and create an audited CSV or print-ready PDF report." /><Notice><b>Use and export only for an approved purpose.</b><p>Exports may include precise site coordinates. They do not certify compliance or water safety. Export actor, filters, row count and format are audited.</p></Notice><div className="panel report-controls"><label>Created from<input type="date" value={from} onChange={(event) => setFrom(event.target.value)} /></label><label>Created to<input type="date" value={to} onChange={(event) => setTo(event.target.value)} /></label><label>Area<select value={district} onChange={(event) => setDistrict(event.target.value)}><option value="">All areas</option>{areas.map((area) => <option key={area}>{area}</option>)}</select></label><label>Operational status<select value={status} onChange={(event) => setStatus(event.target.value)}><option value="">All statuses</option>{[...new Set(records.map((record) => record.operationalStatus))].map((item) => <option key={item}>{item}</option>)}</select></label><label>Report notes<input value={notes} onChange={(event) => setNotes(event.target.value)} maxLength={2000} placeholder="Purpose or scope note" /></label><div className="report-actions"><button className="button button-primary" onClick={() => void exportCsv()} disabled={disabled}><FileCheck2 size={15} /> Export CSV</button><button className="button button-quiet" onClick={() => void exportPdf()} disabled={disabled}>Print / Save PDF</button></div></div>{report.error && <Notice tone="warning"><b>Report unavailable.</b><p>{report.error.message}</p></Notice>}<div className="metric-row"><Metric label="Matching records" value={String(report.data?.length ?? 0)} /><Metric label="Unable to assess" value={String(report.data?.filter((item) => item.screeningStatus === "unable_to_assess").length ?? 0)} /><Metric label="Flagged for review" value={String(report.data?.filter((item) => item.screeningStatus === "flagged_for_review").length ?? 0)} /><Metric label="Areas represented" value={String(new Set(report.data?.map((item) => item.district) ?? []).size)} /></div></>;
}
type WorkspaceUser = { id: number; name: string | null; email: string; role: string; workspaceRoles: Array<{ roleKey: string; roleName: string }> };
function AdminTools({ workspace, users, assignRole, removeRole, notify, canManageUsers, canConfigureLayers }: { workspace: WorkspaceData; users: WorkspaceUser[]; assignRole: (input: { userId: number; roleKey: string }) => Promise<unknown>; removeRole: (input: { userId: number; roleKey: string }) => Promise<unknown>; notify: (message: string) => void; canManageUsers: boolean; canConfigureLayers: boolean }) {
  const [selectedRole, setSelectedRole] = useState<Record<number, string>>({});
  const workspaceQuery = trpc.borewatch.workspace.get.useQuery();
  const updateSource = trpc.borewatch.administration.updateDataSource.useMutation({ onSuccess: () => { notify("Data source metadata saved and audited."); void workspaceQuery.refetch(); }, onError: (error) => notify(error.message) });
  const saveRule = trpc.borewatch.administration.saveScreeningRule.useMutation({ onSuccess: () => { notify("Screening rule version saved and audited."); void workspaceQuery.refetch(); }, onError: (error) => notify(error.message) });
  const saveLayer = trpc.borewatch.administration.saveHazardLayer.useMutation({ onSuccess: () => { notify("GeoJSON layer metadata saved and audited."); void workspaceQuery.refetch(); }, onError: (error) => notify(error.message) });
  const deactivateRule = trpc.borewatch.administration.deactivateScreeningRule.useMutation({ onSuccess: () => { notify("Rule version deactivated and audited."); void workspaceQuery.refetch(); }, onError: (error) => notify(error.message) });
  const [ruleKey, setRuleKey] = useState(""); const [ruleName, setRuleName] = useState(""); const [ruleVersion, setRuleVersion] = useState("1.0"); const [ruleSource, setRuleSource] = useState(workspace.sources[0]?.sourceKey ?? ""); const [ruleReference, setRuleReference] = useState(""); const [ruleApprover, setRuleApprover] = useState(""); const [ruleEffectiveDate, setRuleEffectiveDate] = useState(""); const [ruleActive, setRuleActive] = useState(false); const [ruleExplanation, setRuleExplanation] = useState(""); const [ruleLayerKey, setRuleLayerKey] = useState(workspace.layers[0]?.layerKey ?? ""); const [ruleThreshold, setRuleThreshold] = useState("100"); const [ruleMaxAge, setRuleMaxAge] = useState("365");
  const sourceIsVerified = (() => { const source = workspace.sources.find((item) => item.sourceKey === ruleSource); if (!source?.accessStatus.toLowerCase().includes("verified")) return false; try { const metadata = JSON.parse(source.metadataJson ?? "{}") as { verificationStatus?: string }; return ["verified", "approved"].includes(metadata.verificationStatus?.toLowerCase() ?? ""); } catch { return false; } })();
  return <div className="admin-tools">{canManageUsers && <div className="panel admin-users"><div className="panel-head"><div><span className="eyebrow">USER AND ROLE ADMINISTRATION</span><h2>Accounts</h2></div><UsersRound size={18} /></div>{users.map((user) => <div className="role-row" key={user.id}><div><b>{user.name ?? user.email}</b><small>{user.email} · {user.role === "admin" ? "Platform administrator" : "Standard account"}{user.workspaceRoles.length ? ` · ${user.workspaceRoles.map((role) => role.roleName).join(", ")}` : " · No workspace role"}</small>{user.workspaceRoles.map((role) => <button className="text-action" key={role.roleKey} onClick={async () => { try { await removeRole({ userId: user.id, roleKey: role.roleKey }); notify("Workspace role removed and audited."); } catch (error) { notify(error instanceof Error ? error.message : "Unable to remove role"); } }}>Remove {role.roleName}</button>)}</div><select aria-label={`Workspace role for ${user.email}`} value={selectedRole[user.id] ?? ""} onChange={(event) => setSelectedRole({ ...selectedRole, [user.id]: event.target.value })}><option value="">Choose role</option>{workspace.roles.map((role) => <option key={role.roleKey} value={role.roleKey}>{role.name}</option>)}</select><button className="text-action" disabled={!selectedRole[user.id]} onClick={async () => { try { await assignRole({ userId: user.id, roleKey: selectedRole[user.id] }); notify("Role assigned."); } catch (error) { notify(error instanceof Error ? error.message : "Unable to assign role"); } }}>Assign</button></div>)}{users.length === 0 && <p>No registered accounts.</p>}</div>}{canConfigureLayers && <><div className="panel"><div className="panel-head"><div><span className="eyebrow">SPATIAL DATA</span><h2>Hazard layers</h2></div><Layers3 size={18} /></div>{workspace.layers.map((layer) => <div className="source-card" key={layer.layerKey}><b>{layer.name} · v{layer.version}</b><p>{layer.layerKey} · {layer.sourceKey} · {layer.verificationStatus} · {layer.active ? "active" : "inactive"}</p><small>{layer.coordinateReferenceSystem} · {layer.datasetDate ? new Date(layer.datasetDate).toLocaleDateString() : "date not recorded"} · {layer.accuracyNotes ?? "accuracy not documented"}</small></div>)}<LayerImporter sources={workspace.sources} save={saveLayer.mutateAsync} notify={notify} /></div><div className="panel"><div className="panel-head"><div><span className="eyebrow">DATA GOVERNANCE</span><h2>Source metadata</h2></div><Database size={18} /></div>{workspace.sources.map((source) => <SourceEditor key={source.sourceKey} source={source} save={updateSource.mutateAsync} notify={notify} />)}</div><div className="panel"><div className="panel-head"><div><span className="eyebrow">SCREENING CONFIGURATION</span><h2>Rule provenance</h2></div><Layers3 size={18} /></div><p className="dialog-intro">Rules remain inactive unless an approver, effective date and source reference are supplied. Never enter unvalidated thresholds as legal requirements.</p>{workspace.rules.map((rule) => <div className="source-card" key={`${rule.ruleKey}@${rule.version}`}><b>{rule.name} · {rule.version} {rule.active ? "· ACTIVE" : "· INACTIVE"}</b><p>{rule.explanation}</p><small>Source: {rule.sourceReference ?? "not recorded"} · Approved by: {rule.approvedBy ?? "not recorded"}</small>{rule.active && <button className="text-action" onClick={async () => { const reason = window.prompt(`Why deactivate ${rule.ruleKey}@${rule.version}?`); if (!reason?.trim()) return; try { await deactivateRule.mutateAsync({ ruleKey: rule.ruleKey, version: rule.version, reason: reason.trim() }); } catch (error) { notify(error instanceof Error ? error.message : "Unable to deactivate rule"); } }}>Deactivate with reason</button>}</div>)}<form className="rule-form" onSubmit={async (event) => { event.preventDefault(); try { await saveRule.mutateAsync({ ruleKey, name: ruleName, version: ruleVersion, jurisdiction: "Zimbabwe · pilot area to validate", hazardType: "spatial_screening", conditionJson: JSON.stringify({ type: "distance", layerKey: ruleLayerKey, thresholdMeters: Number(ruleThreshold), maxDatasetAgeDays: Number(ruleMaxAge) }), sourceKey: ruleSource, sourceReference: ruleReference || null, effectiveAt: ruleEffectiveDate ? new Date(`${ruleEffectiveDate}T12:00:00Z`).toISOString() : null, approvedBy: ruleApprover || null, explanation: ruleExplanation, active: ruleActive }); setRuleKey(""); setRuleName(""); setRuleReference(""); setRuleApprover(""); setRuleExplanation(""); setRuleVersion("1.0"); setRuleEffectiveDate(""); setRuleActive(false); } catch (error) { notify(error instanceof Error ? error.message : "Unable to save rule metadata"); } }}><h3>Add screening rule version</h3><label>Rule key<input required value={ruleKey} onChange={(event) => setRuleKey(event.target.value)} /></label><label>Name<input required value={ruleName} onChange={(event) => setRuleName(event.target.value)} /></label><label>Version<input required value={ruleVersion} onChange={(event) => setRuleVersion(event.target.value)} /></label><label>Source<select required value={ruleSource} onChange={(event) => setRuleSource(event.target.value)}>{workspace.sources.map((source) => <option value={source.sourceKey} key={source.sourceKey}>{source.name}</option>)}</select></label><label>Hazard layer<select required value={ruleLayerKey} onChange={(event) => setRuleLayerKey(event.target.value)}><option value="">Choose a spatial layer</option>{workspace.layers.filter((layer) => layer.sourceKey === ruleSource).map((layer) => <option key={layer.layerKey} value={layer.layerKey}>{layer.name} · {layer.version} · {layer.verificationStatus}</option>)}</select></label><label>Distance threshold (metres)<input type="number" min="0" step="0.1" required value={ruleThreshold} onChange={(event) => setRuleThreshold(event.target.value)} /></label><label>Maximum layer age (days)<input type="number" min="1" required value={ruleMaxAge} onChange={(event) => setRuleMaxAge(event.target.value)} /></label><label>Source reference<input value={ruleReference} onChange={(event) => setRuleReference(event.target.value)} placeholder="Document or URL to validate" /></label><label>Approver<input value={ruleApprover} onChange={(event) => setRuleApprover(event.target.value)} placeholder="Authority validation pending" /></label><label>Effective date<input type="date" value={ruleEffectiveDate} onChange={(event) => setRuleEffectiveDate(event.target.value)} /></label><label className="checkline"><input type="checkbox" checked={ruleActive} disabled={!sourceIsVerified || !workspace.layers.some((layer) => layer.layerKey === ruleLayerKey && layer.active && layer.verificationStatus === "verified")} onChange={(event) => setRuleActive(event.target.checked)} />Rule active (requires source verification)</label><label>Explanation<textarea required value={ruleExplanation} onChange={(event) => setRuleExplanation(event.target.value)} /></label><button className="button button-primary" disabled={saveRule.isPending}>{ruleActive ? "Save active rule version" : "Save inactive rule version"}</button></form></div></>}</div>;
}
function LayerImporter({ sources, save, notify }: { sources: WorkspaceData["sources"]; save: (input: { layerKey: string; name: string; sourceKey: string; version: string; geometryJson: string; datasetDate: string | null; coordinateReferenceSystem: "EPSG:4326"; coverageJson: string | null; accuracyNotes: string | null; licenseNotes: string | null; verificationStatus: "unverified" | "verified" | "stale" | "demonstration"; active: boolean }) => Promise<unknown>; notify: (message: string) => void }) {
  const [layerKey, setLayerKey] = useState(""); const [name, setName] = useState(""); const [sourceKey, setSourceKey] = useState(sources[0]?.sourceKey ?? ""); const [version, setVersion] = useState("1.0"); const [datasetDate, setDatasetDate] = useState(""); const [verificationStatus, setVerificationStatus] = useState<"unverified" | "verified" | "stale" | "demonstration">("unverified"); const [active, setActive] = useState(false); const [coverage, setCoverage] = useState("{}"); const [accuracy, setAccuracy] = useState(""); const [license, setLicense] = useState(""); const [geojson, setGeojson] = useState("");
  const source = sources.find((item) => item.sourceKey === sourceKey); const sourceVerified = Boolean(source?.accessStatus.toLowerCase().includes("verified") && (() => { try { return ["verified", "approved"].includes((JSON.parse(source.metadataJson ?? "{}") as { verificationStatus?: string }).verificationStatus?.toLowerCase() ?? ""); } catch { return false; } })());
  return <form className="rule-form" onSubmit={async (event) => { event.preventDefault(); try { await save({ layerKey, name, sourceKey, version, geometryJson: geojson, datasetDate: datasetDate ? new Date(`${datasetDate}T12:00:00Z`).toISOString() : null, coordinateReferenceSystem: "EPSG:4326", coverageJson: coverage || null, accuracyNotes: accuracy || null, licenseNotes: license || null, verificationStatus, active }); setLayerKey(""); setName(""); setGeojson(""); notify("Layer saved. It remains unavailable to screening unless it is verified and active."); } catch (error) { notify(error instanceof Error ? error.message : "Unable to save layer"); } }}><h3>Import a spatial layer</h3><Notice><b>Use authorized data only.</b><p>GeoJSON must use WGS84/EPSG:4326 coordinates. Label synthetic fixtures as demonstration and do not activate them for operational screening.</p></Notice><label>GeoJSON file<input type="file" accept=".geojson,.json,application/geo+json,application/json" onChange={async (event) => { const file = event.target.files?.[0]; if (!file) return; if (file.size > 8_000_000) { notify("Layer files must be 8 MB or smaller"); return; } setGeojson(await file.text()); if (!name) setName(file.name.replace(/\.(geojson|json)$/i, "")); }} /></label><label>Layer key<input required value={layerKey} onChange={(event) => setLayerKey(event.target.value)} placeholder="e.g. sanitation_sites_pilot" /></label><label>Layer name<input required value={name} onChange={(event) => setName(event.target.value)} /></label><label>Source<select required value={sourceKey} onChange={(event) => setSourceKey(event.target.value)}>{sources.map((item) => <option key={item.sourceKey} value={item.sourceKey}>{item.name}</option>)}</select></label><label>Dataset version<input required value={version} onChange={(event) => setVersion(event.target.value)} /></label><label>Dataset date<input type="date" value={datasetDate} onChange={(event) => setDatasetDate(event.target.value)} /></label><label>Verification status<select value={verificationStatus} onChange={(event) => setVerificationStatus(event.target.value as typeof verificationStatus)}><option value="unverified">Unverified</option><option value="demonstration">Synthetic demonstration</option><option value="stale">Stale</option><option value="verified">Verified by responsible reviewer</option></select></label><label>Coverage metadata JSON<textarea value={coverage} onChange={(event) => setCoverage(event.target.value)} /></label><label>Accuracy / CRS notes<input value={accuracy} onChange={(event) => setAccuracy(event.target.value)} /></label><label>License and permission notes<textarea value={license} onChange={(event) => setLicense(event.target.value)} /></label><label className="checkline"><input type="checkbox" checked={active} disabled={!sourceVerified || verificationStatus !== "verified"} onChange={(event) => setActive(event.target.checked)} />Make available to screening (verified source and layer required)</label><label>GeoJSON<textarea required rows={8} value={geojson} onChange={(event) => setGeojson(event.target.value)} placeholder='{"type":"FeatureCollection","features":[]}' /></label><button className="button button-primary" disabled={!geojson}>{"Save layer metadata and GeoJSON"}</button></form>;
}

function SourceEditor({ source, save, notify }: { source: WorkspaceData["sources"][number]; save: (input: { sourceKey: string; purpose: string; accessStatus: string; metadataJson: string | null; active: boolean }) => Promise<unknown>; notify: (message: string) => void }) { const [status, setStatus] = useState(source.accessStatus); const [purpose, setPurpose] = useState(source.purpose); const [metadata, setMetadata] = useState(source.metadataJson ?? "{}"); return <form className="source-editor" onSubmit={async (event) => { event.preventDefault(); try { await save({ sourceKey: source.sourceKey, purpose, accessStatus: status, metadataJson: metadata, active: true }); } catch (error) { notify(error instanceof Error ? error.message : "Unable to update source"); } }}><h3>{source.name} <small>{source.sourceKey}</small></h3><label>Purpose<textarea required maxLength={2000} value={purpose} onChange={(event) => setPurpose(event.target.value)} /></label><label>Availability and verification status<input required maxLength={255} value={status} onChange={(event) => setStatus(event.target.value)} /></label><label>Metadata JSON<textarea value={metadata} onChange={(event) => setMetadata(event.target.value)} /></label><button className="button button-quiet">Save source metadata</button></form>; }
function Administration({ workspace, authority, setAuthority, notify, users, assignRole, removeRole, canManageUsers, canConfigureLayers, canManageSettings, canAudit }: { workspace: WorkspaceData; authority: string; setAuthority: (value: string) => void; notify: (message: string) => void; users: WorkspaceUser[]; assignRole: (input: { userId: number; roleKey: string }) => Promise<unknown>; removeRole: (input: { userId: number; roleKey: string }) => Promise<unknown>; canManageUsers: boolean; canConfigureLayers: boolean; canManageSettings: boolean; canAudit: boolean }) {
  const audit = trpc.borewatch.administration.audit.useQuery(undefined, { enabled: canAudit });
  const workspaceQuery = trpc.borewatch.workspace.get.useQuery();
  const [workflowJson, setWorkflowJson] = useState(JSON.stringify(workspace.settings.workflow, null, 2));
  useEffect(() => setWorkflowJson(JSON.stringify(workspace.settings.workflow, null, 2)), [workspace.settings.workflow]);
  const save = trpc.borewatch.administration.updateSettings.useMutation({ onSuccess: () => { notify("Workspace settings saved and audited."); void audit.refetch(); void workspaceQuery.refetch(); }, onError: (error) => notify(error.message) });
  const validationStatus = (workspace.settings.workflow as { validationStatus?: string }).validationStatus;
  return <><TitleBlock eyebrow="SERVER CONFIGURATION" title="Administration" detail="Manage assigned permissions, verified source metadata, workflow settings and read-only history." />
    {canManageUsers && <div className="panel role-panel"><div className="panel-head"><div><span className="eyebrow">ROLES AND PERMISSIONS</span><h2>Configured roles</h2></div><UsersRound size={18} /></div>{workspace.roles.map((role) => { let permissions: string[] = []; try { permissions = JSON.parse(role.permissionsJson) as string[]; } catch { permissions = []; } return <div className="role-row" key={role.roleKey}><div className="role-icon"><UsersRound size={16} /></div><div><b>{role.name}</b><small>{permissions.join(" · ")}</small></div><Badge>{role.roleKey}</Badge></div>; })}</div>}
    {(canManageUsers || canConfigureLayers) && <AdminTools workspace={workspace} users={users} assignRole={assignRole} removeRole={removeRole} notify={notify} canManageUsers={canManageUsers} canConfigureLayers={canConfigureLayers} />}
    {canManageSettings && <><div className="panel data-panel"><div className="panel-head"><div><span className="eyebrow">GOVERNANCE</span><h2>{workspace.settings.coordinatingAuthority}</h2></div><ShieldCheck size={18} /></div><label className="config-field"><span>{workspace.settings.localAuthorityLabel}</span><input value={authority} onChange={(event) => setAuthority(event.target.value)} placeholder="Set the local council" /></label><label className="config-field"><span>Workflow JSON · validate transitions before saving</span><textarea rows={12} value={workflowJson} onChange={(event) => setWorkflowJson(event.target.value)} /></label><button className="button button-primary" disabled={save.isPending} onClick={() => save.mutate({ localAuthorityValue: authority || null, workflowJson })}><Check size={15} /> {save.isPending ? "Saving…" : "Save server configuration"}</button></div><div className="panel workflow-config"><div className="panel-head"><div><span className="eyebrow">WORKFLOW</span><h2>Configured stages</h2></div><Badge tone={validationStatus === "pending_authority_validation" ? "amber" : "soft"}>{validationStatus === "pending_authority_validation" ? "Pending authority validation" : "Server-enforced"}</Badge></div><div className="workflow-stage-list">{((workspace.settings.workflow as { stages?: Array<{ key: string; label: string; allowedNext: string[] }> }).stages ?? []).map((stage, index) => <div className="workflow-stage" key={stage.key}><span className="stage-number">{index + 1}</span><b>{stage.label}</b><small>Next: {stage.allowedNext.join(", ") || "No further stage"}</small></div>)}</div></div></>}
    {canAudit && <div className="panel"><div className="panel-head"><div><span className="eyebrow">READ ONLY HISTORY</span><h2>Recent audit events</h2></div><Badge>{audit.data?.length ?? 0} events</Badge></div>{audit.isLoading ? <p>Loading audit history…</p> : audit.error ? <Notice tone="warning"><b>Audit history unavailable.</b><p>{audit.error.message}</p></Notice> : audit.data?.length ? <div className="audit-list">{audit.data.map((event) => <div className="audit-row" key={event.id}><time>{new Date(event.createdAt).toLocaleString()}</time><b>{event.action}</b><span>{event.resourceType}: {event.resourceId}</span><small>Actor ID {event.actorId}</small></div>)}</div> : <div className="empty-state"><span>No audit events recorded yet.</span></div>}</div>}
    <Notice><b>Hosting boundary</b><p>Public information belongs on {workspace.settings.publicHosting}; authenticated records, evidence, permissions and audit history belong on {workspace.settings.privateHosting}.</p></Notice>
  </>;
}
function EvidencePanel({ entityType, entityId, canUpload, showDocumentType = false }: { entityType: "application" | "inspection"; entityId: number; canUpload: boolean; showDocumentType?: boolean }) { const evidence = trpc.borewatch.evidence.list.useQuery({ entityType, entityId }); const upload = trpc.borewatch.evidence.upload.useMutation({ onSuccess: () => void evidence.refetch() }); const [documentType, setDocumentType] = useState<string>(requiredApplicationDocuments[0]); const add = async (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.currentTarget.files?.[0]; event.currentTarget.value = ""; if (!file) return; if (file.size < 1 || file.size > 10 * 1024 * 1024 || !isEvidenceMime(file.type)) return; const bytes = new Uint8Array(await file.arrayBuffer()); let binary = ""; for (let offset = 0; offset < bytes.length; offset += 0x8000) binary += String.fromCharCode(...bytes.subarray(offset, offset + 0x8000)); try { await upload.mutateAsync({ entityType, entityId, fileName: file.name, contentType: file.type, contentBase64: btoa(binary), documentType: showDocumentType ? documentType : undefined }); } catch { /* the visible query error reports the upload failure */ } }; return <section className="evidence-panel"><h3>Private supporting evidence</h3>{showDocumentType && <label>Document category<select value={documentType} onChange={(event) => setDocumentType(event.target.value)}>{requiredApplicationDocuments.map((key) => <option key={key} value={key}>{key.replaceAll("_", " ")}</option>)}</select></label>}{canUpload && <label className="button button-quiet evidence-upload"><Upload size={14} />{upload.isPending ? "Uploading…" : "Upload PDF / image"}<input type="file" accept="application/pdf,image/jpeg,image/png" disabled={upload.isPending} onChange={(event) => void add(event)} /></label>}{evidence.isLoading ? <p>Loading evidence…</p> : evidence.error ? <p role="alert">Evidence unavailable: {evidence.error.message}</p> : evidence.data?.length ? <ul className="evidence-list">{evidence.data.map((file) => <li key={file.id}><a href={file.downloadUrl} target="_blank" rel="noreferrer">{file.fileName}</a><small>{file.documentType?.replaceAll("_", " ") ?? "Supporting evidence"} · {(file.byteSize / 1024).toFixed(1)} KB · {new Date(file.createdAt).toLocaleString()}</small></li>)}</ul> : <p>No files attached. Each file is stored privately and downloads use short-lived links.</p>}</section>; }
function RecordDrawer({ record, close, canUpload, canEdit, canViewParty, currentUserId, onUpdate, update, notify }: { record: RecordView; close: () => void; canUpload: boolean; canEdit: boolean; canViewParty: boolean; currentUserId: number; onUpdate: (record: RecordView) => void; update: (input: { id: number; siteName: string; district: string; purpose: string; latitude: string; longitude: string; operationalStatus: string; commissionedAt?: string | null; decommissionedAt?: string | null; decommissionReason?: string | null; locationDescription: string | null; technicalDetails: Record<string, string> }) => Promise<RecordView>; notify: (message: string) => void }) {
  const evidence = trpc.borewatch.evidence.list.useQuery({ entityType: "borehole", entityId: record.id });
  const upload = trpc.borewatch.evidence.upload.useMutation({ onSuccess: () => void evidence.refetch() });
  const partyQuery = trpc.borewatch.boreholes.party.get.useQuery({ boreholeId: record.id }, { enabled: canViewParty || record.createdBy === currentUserId });
  const updateParty = trpc.borewatch.boreholes.party.update.useMutation({ onSuccess: () => { void partyQuery.refetch(); notify("Responsible-party details saved and audited."); }, onError: (error) => notify(error.message) });
  const [partyName, setPartyName] = useState(""); const [partyOrganization, setPartyOrganization] = useState(""); const [partyEmail, setPartyEmail] = useState(""); const [partyPhone, setPartyPhone] = useState("");
  useEffect(() => { if (partyQuery.data) { setPartyName(partyQuery.data.displayName); setPartyOrganization(partyQuery.data.organization ?? ""); setPartyEmail(partyQuery.data.contactEmail ?? ""); setPartyPhone(partyQuery.data.contactPhone ?? ""); } }, [partyQuery.data]);
  const [siteName, setSiteName] = useState(record.siteName); const [district, setDistrict] = useState(record.district); const [purpose, setPurpose] = useState(record.purpose); const [latitude, setLatitude] = useState(record.latitude); const [longitude, setLongitude] = useState(record.longitude); const [locationDescription, setLocationDescription] = useState(record.locationDescription ?? ""); const [operationalStatus, setOperationalStatus] = useState(record.operationalStatus); const [commissionedDate, setCommissionedDate] = useState(record.commissionedAt ? new Date(record.commissionedAt).toISOString().slice(0, 10) : ""); const [decommissionedDate, setDecommissionedDate] = useState(record.decommissionedAt ? new Date(record.decommissionedAt).toISOString().slice(0, 10) : ""); const [decommissionReason, setDecommissionReason] = useState(record.decommissionReason ?? "");
  let initialDetails: Record<string, string> = {}; try { initialDetails = JSON.parse(record.technicalDetailsJson ?? "{}") as Record<string, string>; } catch { initialDetails = {}; }
  const [technicalDetails, setTechnicalDetails] = useState(initialDetails); const [depth, setDepth] = useState(initialDetails.totalDepthM ?? ""); const [coordinateAccuracy, setCoordinateAccuracy] = useState(initialDetails.coordinateAccuracyM ?? ""); const [coordinateCapturedDate, setCoordinateCapturedDate] = useState(initialDetails.coordinateCapturedDate ?? ""); const [construction, setConstruction] = useState(initialDetails.construction ?? ""); const [saving, setSaving] = useState(false);
  const saveRecord = async (event: React.FormEvent) => { event.preventDefault(); if (operationalStatus === "decommissioned" && !window.confirm("Mark this borehole as decommissioned? Confirm that the status and supporting evidence have been reviewed.")) return; setSaving(true); try { const updated = await update({ id: record.id, siteName, district, purpose, latitude, longitude, operationalStatus, commissionedAt: commissionedDate ? new Date(`${commissionedDate}T12:00:00Z`).toISOString() : null, decommissionedAt: decommissionedDate ? new Date(`${decommissionedDate}T12:00:00Z`).toISOString() : null, decommissionReason: decommissionReason || null, locationDescription: locationDescription || null, technicalDetails: { ...technicalDetails, coordinateReferenceSystem: "EPSG:4326", ...(coordinateAccuracy ? { coordinateAccuracyM: coordinateAccuracy } : {}), ...(coordinateCapturedDate ? { coordinateCapturedDate } : {}), ...(depth ? { totalDepthM: depth } : {}), ...(construction ? { construction } : {}) } }); onUpdate(updated); notify("Borehole details saved and before/after changes audited."); } catch (error) { notify(error instanceof Error ? error.message : "Unable to update borehole"); } finally { setSaving(false); } };
  const addFile = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.currentTarget.files?.[0];
    event.currentTarget.value = "";
    if (!file) return;
    if (file.size < 1 || file.size > 10 * 1024 * 1024) {
      notify("Evidence files must be between 1 byte and 10 MB.");
      return;
    }
    if (!isEvidenceMime(file.type)) {
      notify("Only PDF, JPEG, or PNG evidence files are accepted.");
      return;
    }
    try {
      const bytes = new Uint8Array(await file.arrayBuffer());
      let binary = "";
      for (let offset = 0; offset < bytes.length; offset += 0x8000) {
        binary += String.fromCharCode(...bytes.subarray(offset, offset + 0x8000));
      }
      await upload.mutateAsync({
        entityType: "borehole",
        entityId: record.id,
        fileName: file.name,
        contentType: file.type,
        contentBase64: btoa(binary),
      });
      notify("Evidence uploaded to private Neon Object Storage.");
    } catch (error) {
      notify(error instanceof Error ? error.message : "Evidence upload failed.");
    }
  };
  return <div className="drawer-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) close(); }}><aside className="record-drawer"><div className="drawer-top"><span className="eyebrow">DATABASE RECORD</span><button className="icon-button" onClick={close} aria-label="Close"><X size={18} /></button></div><div className="drawer-title"><div className="record-avatar drawer-avatar">{record.siteName.slice(0, 2).toUpperCase()}</div><div><h2>{record.siteName}</h2><span>{record.recordCode}</span></div></div>{(canViewParty || record.createdBy === currentUserId) && <form className="drawer-section record-edit-form" onSubmit={async (event) => { event.preventDefault(); try { await updateParty.mutateAsync({ boreholeId: record.id, displayName: partyName, organization: partyOrganization || null, contactEmail: partyEmail || null, contactPhone: partyPhone || null }); } catch (error) { notify(error instanceof Error ? error.message : "Unable to save responsible party"); } }}><span className="eyebrow">RESPONSIBLE PARTY · RESTRICTED</span>{partyQuery.isLoading ? <p>Loading contact details…</p> : <><label>Name<input required value={partyName} onChange={(event) => setPartyName(event.target.value)} maxLength={255} /></label><label>Organization<input value={partyOrganization} onChange={(event) => setPartyOrganization(event.target.value)} maxLength={255} /></label><label>Contact email<input type="email" value={partyEmail} onChange={(event) => setPartyEmail(event.target.value)} maxLength={320} /></label><label>Contact phone<input type="tel" value={partyPhone} onChange={(event) => setPartyPhone(event.target.value)} maxLength={64} /></label><button className="button button-quiet" disabled={updateParty.isPending}>Save responsible party</button></>}</form>}{!canViewParty && record.createdBy !== currentUserId && <div className="drawer-section"><b>Responsible-party details</b><p>Restricted to the record creator and users with party-view permission.</p></div>}{canEdit && <form className="drawer-section record-edit-form" onSubmit={(event) => void saveRecord(event)}><span className="eyebrow">EDIT RECORD DETAILS</span><label>Site name<input required maxLength={255} value={siteName} onChange={(event) => setSiteName(event.target.value)} /></label><label>District / area<input required maxLength={160} value={district} onChange={(event) => setDistrict(event.target.value)} /></label><label>Purpose<input required maxLength={160} value={purpose} onChange={(event) => setPurpose(event.target.value)} /></label><label>Location description<input value={locationDescription} onChange={(event) => setLocationDescription(event.target.value)} /></label><div className="coordinate-fields"><label>Latitude<input required value={latitude} onChange={(event) => setLatitude(event.target.value)} /></label><label>Longitude<input required value={longitude} onChange={(event) => setLongitude(event.target.value)} /></label></div><label>Total depth (m)<input type="number" min="0" step="0.1" value={depth} onChange={(event) => setDepth(event.target.value)} /></label><label>Construction notes<textarea value={construction} onChange={(event) => setConstruction(event.target.value)} /></label><label>Coordinate accuracy (m)<input type="number" min="0" step="0.1" value={coordinateAccuracy} onChange={(event) => setCoordinateAccuracy(event.target.value)} /></label><label>Coordinate capture date<input type="date" value={coordinateCapturedDate} onChange={(event) => setCoordinateCapturedDate(event.target.value)} /></label><label>Commissioning date<input type="date" value={commissionedDate} onChange={(event) => setCommissionedDate(event.target.value)} /></label><label>Operational status<select value={operationalStatus} onChange={(event) => setOperationalStatus(event.target.value)}>{["unverified", "registered", "active", "inactive", "under_investigation", "decommissioned"].map((value) => <option key={value} value={value}>{value.replaceAll("_", " ")}</option>)}</select></label>{operationalStatus === "decommissioned" && <><label>Decommission date<input required type="date" value={decommissionedDate} onChange={(event) => setDecommissionedDate(event.target.value)} /></label><label>Decommission reason<textarea required value={decommissionReason} onChange={(event) => setDecommissionReason(event.target.value)} maxLength={2000} /></label></>}<button className="button button-primary" disabled={saving}>{saving ? "Saving…" : "Save record details"}</button></form>}<div className="drawer-section"><div className="drawer-statuses"><div><small>Operational status</small><Badge>{record.operationalStatus}</Badge></div><div><small>Application status</small><Badge tone="blue">{record.applicationStatus}</Badge></div></div></div><div className="drawer-section"><dl className="detail-list"><div><dt>District / area</dt><dd>{record.district}</dd></div><div><dt>Purpose</dt><dd>{record.purpose}</dd></div><div><dt>Coordinates</dt><dd>{record.latitude}, {record.longitude}</dd></div><div><dt>Location description</dt><dd>{record.locationDescription || "Not provided"}</dd></div><div><dt>Total depth</dt><dd>{(() => { try { return JSON.parse(record.technicalDetailsJson ?? "{}").totalDepthM ? `${JSON.parse(record.technicalDetailsJson ?? "{}").totalDepthM} m` : "Not provided"; } catch { return "Details unavailable"; } })()}</dd></div><div><dt>Screening</dt><dd>{record.screeningStatus}</dd></div><div><dt>Commissioned</dt><dd>{record.commissionedAt ? new Date(record.commissionedAt).toLocaleDateString() : "Not recorded"}</dd></div><div><dt>Decommissioned</dt><dd>{record.decommissionedAt ? `${new Date(record.decommissionedAt).toLocaleDateString()} · ${record.decommissionReason ?? "Reason not recorded"}` : "Not recorded"}</dd></div></dl></div><div className="drawer-section"><span className="eyebrow">PRIVATE EVIDENCE</span>{canUpload && <label className="button button-quiet evidence-upload"><Upload size={14} />{upload.isPending ? "Uploading…" : "Upload file"}<input type="file" accept="application/pdf,image/jpeg,image/png" disabled={upload.isPending} onChange={(event) => void addFile(event)} /></label>}{evidence.isLoading ? <p>Loading evidence…</p> : evidence.error ? <p>Evidence unavailable: {evidence.error.message}</p> : evidence.data?.length ? <ul className="evidence-list">{evidence.data.map((file) => <li key={file.id}><a href={file.downloadUrl} target="_blank" rel="noreferrer">{file.fileName}</a><small>{(file.byteSize / 1024).toFixed(1)} KB · {new Date(file.createdAt).toLocaleString()}</small></li>)}</ul> : <p>No evidence files attached.</p>}<small>PDF, JPEG, or PNG; maximum 10 MB. Downloads use short-lived signed links.</small></div><Notice><b>Human review required</b><p>Screening status is a configured application value, not a regulatory conclusion.</p></Notice></aside></div>;
}
function Modal({ title, close, children }: { title: string; close: () => void; children: React.ReactNode }) { return <div className="modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) close(); }}><section className="dialog" role="dialog" aria-modal="true"><div className="dialog-top"><h2>{title}</h2><button className="icon-button" onClick={close} aria-label="Close"><X size={18} /></button></div>{children}</section></div>; }
